import itertools

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def calculate_S(n, k, L):
    """Calculates the set S of all n-digit binary strings that differ from L in exactly k positions."""
    all_strings = []
    for i in range(2**n):
        s = bin(i)[2:].zfill(n)
        if hamming_distance(L, s) == k:
            all_strings.append(s)
    return set(all_strings)

n = 3
k = 1
L_list = ["000", "001", "010", "011", "100", "101", "110", "111"]
S_map = {}

# Calculate S(L) for all L
for L in L_list:
    S_L = calculate_S(n, k, L)
    S_map[L] = S_L

# Check for uniqueness: are there any two distinct L1, L2 such that S(L1) == S(L2)?
is_unique = True
L_keys = list(S_map.keys())
for i in range(len(L_keys)):
    for j in range(i + 1, len(L_keys)):
        L1 = L_keys[i]
        L2 = L_keys[j]
        if S_map[L1] == S_map[L2]:
            is_unique = False
            print(f"Counterexample found: S({L1}) == S({L2})")
            break
    if not is_unique:
        break

print(f"Is S(L) unique for n={n}, k={k}? {is_unique}")

import itertools

def hamming_distance(s1, s2):
    return sum(c1 != c2 for c1, c2 in zip(s1, s2))

def generate_sphere(n, k, center_string):
    """Generates the set S of strings at Hamming distance k from center_string."""
    strings = []
    all_strings = [''.join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]
    for s in all_strings:
        if hamming_distance(center_string, s) == k:
            strings.append(s)
    return set(strings)

def find_all_centers(n, k):
    """Finds all centers L such that S(L) is observed."""
    all_strings = [''.join(map(str, p)) for p in itertools.product([0, 1], repeat=n)]
    center_to_set = {}

    # 1. Map each potential center L to its unique set S(L)
    for L in all_strings:
        S = generate_sphere(n, k, L)
        center_to_set[L] = S

    # 2. Check which sets S are generated by multiple centers
    set_to_centers = {}
    for L, S in center_to_set.items():
        if S not in set_to_centers:
            set_to_centers[S] = []
        set_to_centers[S].append(L)

    # 3. Find the maximum number of centers M
    M_max = 0
    for S in set_to_centers:
        M_max = max(M_max, len(set_to_centers[S]))

    return M_max

